import { useEffect, useState } from 'react'
import type { FormEvent } from 'react'
import { Link, Navigate, useNavigate } from 'react-router-dom'

import { apiClient } from '../../services/apiClient'
import { useAppDispatch, useAppSelector } from '../../store/hooks'
import { registerDoctorUser } from '../../store/slices/authSlice'
import logoUrl from '../../assets/logo.png'

export function DoctorRegisterPage() {
  const dispatch = useAppDispatch()
  const navigate = useNavigate()
  const { isAuthenticated, user, status, error: authError } = useAppSelector((state) => state.auth)
  const [error, setError] = useState('')
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    try {
      return (globalThis.localStorage?.getItem('fv-theme') as 'light' | 'dark') || 'light'
    } catch {
      return 'light'
    }
  })

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme)
  }, [theme])

  const setAppTheme = (nextTheme: 'light' | 'dark') => {
    setTheme(nextTheme)
    document.documentElement.setAttribute('data-theme', nextTheme)
    try {
      globalThis.localStorage?.setItem('fv-theme', nextTheme)
    } catch {
      // persistence is a convenience; ignore a blocked or unavailable store
    }
  }

  if (isAuthenticated) return <Navigate to={user?.role === 'DOCTOR' ? '/doctor-status' : '/dashboard'} replace />

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const registration = {
      displayName: String(form.get('displayName') ?? '').trim(),
      email: String(form.get('email') ?? '').trim(),
      password: String(form.get('password') ?? ''),
    }
    if (!registration.displayName || !registration.email.includes('@') || registration.password.length < 8) {
      setError('Enter a valid name, email, and password of at least 8 characters.')
      return
    }
    const result = await dispatch(registerDoctorUser(registration))
    if (!registerDoctorUser.fulfilled.match(result)) return
    try {
      await apiClient.post('/doctors/register', {
        registrationNumber: String(form.get('registrationNumber') ?? '').trim(),
        specialty: String(form.get('specialty') ?? '').trim() || null,
      })
    } catch {
      setError('Account created, but the synthetic doctor profile needs attention. Continue to status to resume.')
    }
    navigate('/doctor-status', { replace: true })
  }

  return (
    <main className="login-page">
      {/* Top right clean theme toggle */}
      <div className="login-topbar">
        <div className="theme-toggle-group" role="group" aria-label="Theme mode switcher">
          <button
            type="button"
            className={`theme-toggle-btn ${theme === 'light' ? 'active' : ''}`}
            onClick={() => setAppTheme('light')}
          >
            <span aria-hidden="true">☀️</span> Light
          </button>
          <button
            type="button"
            className={`theme-toggle-btn ${theme === 'dark' ? 'active' : ''}`}
            onClick={() => setAppTheme('dark')}
          >
            <span aria-hidden="true">🌙</span> Dark
          </button>
        </div>
      </div>

      {/* Central Clinician Registration Stage */}
      <div className="login-stage">
        {/* Left floating live indicators */}
        <aside className="login-wing login-wing--left" aria-hidden="true">
          <div className="live-floating-card live-floating-card--1">
            <span className="live-icon-badge">🩺</span>
            <div>
              <strong>Clinical Queue</strong>
              <small><span className="pulse-dot" /> Triage review gate</small>
            </div>
          </div>
          <div className="live-floating-card live-floating-card--2">
            <span className="live-icon-badge">🔬</span>
            <div>
              <strong>Diagnostic Context</strong>
              <small>Multi-source extraction</small>
            </div>
          </div>
          <div className="live-floating-card live-floating-card--3">
            <span className="live-icon-badge">🛡️</span>
            <div>
              <strong>SLMC Verified</strong>
              <small>Strict compliance</small>
            </div>
          </div>
        </aside>

        {/* Clean centered expanded doctor registration card */}
        <div className="simple-login-card simple-login-card--wide">
          <div className="simple-login-brand">
            <img src={logoUrl} alt="Family Veda" width={56} height={56} />
            <h1>Family Veda</h1>
            <p>Clinician enrolment</p>
          </div>

          <p className="eyebrow">Synthetic clinician enrolment</p>
          <h2>Create doctor account</h2>
          <p className="muted">Clinical access remains blocked until an administrator verifies the profile. Never enter real medical credentials.</p>

          <form onSubmit={submit} className="register-form-grid" noValidate>
            <label className="field">
              <span>Display name</span>
              <input name="displayName" placeholder="e.g. Dr. Kasun Perera" required maxLength={120} />
            </label>
            <label className="field">
              <span>Email address</span>
              <input name="email" type="email" placeholder="doctor@example.invalid" required />
            </label>
            <label className="field">
              <span>Synthetic SLMC registration identifier</span>
              <input name="registrationNumber" placeholder="e.g. SLMC-SYNTH-9941" minLength={4} maxLength={30} required />
            </label>
            <label className="field">
              <span>Specialty (optional)</span>
              <input name="specialty" placeholder="e.g. General Practice / Paediatrics" maxLength={120} />
            </label>
            <label className="field field--full">
              <span>Password</span>
              <input name="password" type="password" placeholder="At least 8 characters" minLength={8} required />
            </label>
            {(error || authError) && <p className="form-error field--full" role="alert">{error || authError}</p>}
            <button className="button button--primary button--full field--full" type="submit" disabled={status === 'loading'}>
              {status === 'loading' ? 'Creating account…' : 'Submit for verification'}
            </button>
          </form>

          <p className="privacy-note">Already registered? <Link to="/login">Return to sign in</Link></p>
          <p className="privacy-note">Need a family account instead? <Link to="/register">Register family</Link></p>
        </div>

        {/* Right floating live indicators */}
        <aside className="login-wing login-wing--right" aria-hidden="true">
          <div className="live-floating-card live-floating-card--4">
            <span className="live-icon-badge">⚖️</span>
            <div>
              <strong>Advisory Authorisation</strong>
              <small>Doctor approval required</small>
            </div>
          </div>
          <div className="live-floating-card live-floating-card--5">
            <span className="live-icon-badge">🧬</span>
            <div>
              <strong>Familial Risk Insights</strong>
              <small>Hereditary alerts</small>
            </div>
          </div>
          <div className="live-floating-card live-floating-card--6">
            <span className="live-icon-badge">⚡</span>
            <div>
              <strong>SLA Response Clock</strong>
              <small>Active monitoring</small>
            </div>
          </div>
        </aside>
      </div>
    </main>
  )
}
